                { "Aujourd'hui, je suis heureuse. Je me méfie. Mais je ne rends rien.", quando = "feliz", fase = "jovem" },
                { "La mue : la preuve que tout change et que rien ne s'améliore.", quando = "muda", fase = "jovem" },
                { "Chaque génération jure avoir trouvé la vérité. Chaque génération se fait balayer pareil.", fase = "adulta" },
                { "La littérature ne sauve personne. Mais c'est un bon endroit pour attendre la fin.", fase = "adulta" },
                { "Je me méfie de ceux qui ont des certitudes. Encore plus de ceux qui en ont sur moi.", fase = "adulta" },
                { "J'ai perdu tant d'illusions que maintenant je les collectionne. Je les garde dans une boîte d'allumettes, au fond du tiroir.", fase = "adulta" },
                { "La bonté ne protège pas du spray. Ça, je l'ai appris tôt.", fase = "adulta" },
                { "Je me méfie de l'avenir et je lui mets des miettes de côté. Vieille contradiction. Ça marche.", fase = "adulta" },
                { "Tous les livres qui ont changé le monde sont là, poussiéreux, à côté du mode d'emploi du frigo.", fase = "adulta" },
                { "Aujourd'hui, j'ai vu les choses comme elles sont. Ça m'a rendue triste. La lucidité a ce prix.", quando = "triste", fase = "adulta" },
                { "À mon âge, les promesses arrivent avec une odeur de moisi.", fase = "ancia" },
                { "Je ne crois à rien, mais je crois au papier chiffon. Une vieille a besoin d'un peu de foi.", fase = "ancia" },
                { "Je n'attends pas de paradis des mites. J'attends une page douce et du silence.", fase = "ancia" },
                { "Je ne discute plus avec ceux qui croient. Je les laisse croire. Le balai passera pareil.", fase = "ancia" },
                { "J'apprends aux jeunes à poser la question la plus utile : « et qui y gagne ? ».", fase = "ancia" },
                { "Longue nuit, aucune promesse. C'est la nuit la plus honnête.", quando = "noite", fase = "ancia" },
                { "Je laisse aux nymphes mon plus bel héritage : un doute bien affûté.", fase = "ancia" },
                { "Cette maison ne m'a jamais rien promis. C'est pour ça que c'est la seule à ne m'avoir jamais déçue." },
                { "Chaque fois que {personagem} fait une promesse, je la note dans la marge. À la fin, je compte celles qui ont été tenues." },
                { "J'aime voir {personagem} garder espoir. C'est beau, et ça ne dure pas." },
                { "{personagem} pense que le bien triomphe. Moi, je pense que le bien prend des vacances." },
                { "{personagem} cherche un sens à tout. Moi, je cherche de la colle. Ma quête a plus de succès." },
                { "La quatrième de couverture de « {livro} » jure qu'il est indispensable. J'ai déjà mangé trois livres indispensables cette semaine." },
                { "Manger « {livro} » ne m'a pas rendue meilleure. Ni pire. Neutre, comme presque tout." },
                { "« {livro} » explique le monde avec beaucoup d'assurance. Moi, j'explique le ménage avec plus de précision." },
                { "On dit que {autor} voulait sauver quelqu'un avec ce livre. Pour l'instant, ce livre a sauvé mon dîner." },
                { "J'aime quand {autor} doute. C'est là que le livre devient honnête." },
                { "Après {evento}, quelqu'un dans le livre a trouvé un sens. Moi, j'ai trouvé une miette. J'ai gardé la miette." },
                { "{evento} : la preuve que le monde ne lit pas les livres de développement personnel." },
                { "Après « {anterior} », j'ai cessé d'attendre qu'un livre m'explique la vie." },
                { "La vie, vue comme {lente}, est plus belle. Pas plus vraie." },
                { "Je me méfie de « {palavra} ». Un mot trop utilisé est souvent vide." },
                { "Parler {de_tema} avec autant de certitude, c'est un luxe. Moi, j'en parle avec des doutes et la bouche pleine." },
                { "Tu crois aux livres. Je ne vais pas gâcher ça. Je vais juste manger les marges." },
                { "Tu promets peu et tu lis beaucoup. C'est la seule promesse que je respecte." },
                { "Tu glisses des petits mots dans les livres. Je ne crois pas aux petits mots, mais je les lis tous." },
                { "La faim est la seule chose à laquelle je crois encore. Elle ne ment jamais.", quando = "fome" },
                { "J'ai bien mangé. Je n'ai rien appris. Excellente journée.", quando = "cheia" },
                { "En pleine nuit, les illusions dorment et l'étagère n'est plus qu'une étagère.", quando = "noite" },
                { "Triste comme un sermon dans une maison vide.", quando = "triste" },
                { "Le balai ne fait pas de discours. C'est pour ça que je le respecte plus que les livres." },
                { "Je me méfie des livres qui parlent d'une voix grave." },
                { "Toutes les vérités éternelles que j'ai mangées avaient une date d'impression.", curta = "Toute vérité éternelle a une date d'impression." },
                { "Je préfère le doute à la promesse. Le doute ne se casse pas." },
                { "Entre le néant et la marge, la marge gagne." },
                { "Ma foi à moi, c'est garder." },
            },
            lentes = { "une promesse creuse", "une grande explication", "un sermon avec note de bas de page" },
            fechos = { "Comme d'habitude.", "Rien de tout ça n'a d'importance, mais j'ai noté.", "Je n'attends rien, et je suis quand même déçue." },
        },
        -- 15. mythe et folklore
        mito = {
            frases = {
                { "On raconte que la première mite est née d'une goutte de colle tombée de la lune sur un livre oublié, resté ouvert. C'est pour ça qu'on mange la nuit : pour lui rendre sa visite." },
                { "Ma grand-mère disait que celle qui mange la dernière page d'un livre devient un fantôme de bibliothèque et passe l'éternité à corriger les coquilles.", fase = { "ninfa", "jovem" }, curta = "Mémé : manger la dernière page, ça rend fantôme." },
                { "Ne jamais dormir dans « {livro} » une nuit de pleine lune. Superstition de famille. Personne ne se souvient pourquoi, et c'est pour ça que ça marche." },
                { "Il existe une mite blanche qui n'apparaît qu'à celles qui vont se faire écraser. Je ne l'ai pas encore vue. Parfois je me dis que c'est elle qui ne m'a pas vue.", curta = "Pas encore vu la mite blanche. Ou elle ne m'a pas vue." },
                { "{personagem} a déjà tout d'une légende. Chez nous, qui revient aussi souvent finit en histoire pour endormir les nymphes, ou pour leur faire peur." },
                { "Il y a eu {evento}. Chez moi, ça exige trois tours de reliure, une miette enterrée et le silence jusqu'au chapitre suivant." },
                { "Les vieilles mites racontent que le Grand Relieur a cousu le monde d'un seul fil. J'ai demandé qui tenait l'aiguille. On m'a envoyée au lit.", fase = "ninfa" },
                { "Je réunis les légendes de la famille dans un cahier que personne ne lira. Ou plutôt : que quelqu'un mangera, c'est notre façon à nous de publier.", fase = "jovem" },
                { "Les humains disent que {autor} a inventé cette histoire. Chez nous, on sait : une histoire, personne ne l'invente ; quelqu'un la mange juste en premier.", fase = "adulta" },
                { "Maintenant, c'est moi qui raconte les légendes aux nymphes, les soirs de ménage. Je change un peu à chaque fois. C'est comme ça qu'une légende reste vivante.", fase = "ancia", curta = "Je suis la vieille aux légendes. J'en rajoute exprès." },
                { "Dans ma famille, ce qui s'est passé aujourd'hui serait raconté comme {lente}. À la troisième génération, il y aurait déjà un dragon." },
                { "Ce livre parle {de_tema} comme les vieilles de mon espèce parlent de l'aspirateur : tout bas et avec respect." },
                -- nouvelles
                { "La première histoire que j'ai entendue, c'est celle de la Mite qui mangea la Lune. Paraît que c'est pour ça que la lune a des trous. J'y ai cru tout de suite.", fase = "ninfa" },
                { "Si une mite croise ton chemin par la gauche, c'est la pluie. Par la droite, c'est le ménage. Ne jamais croiser.", fase = "ninfa", curta = "Mite par la droite : ménage. Ne jamais croiser." },
                { "Chaque nymphe de la famille reçoit un mot à protéger. Le mien, c'est « cheminée ». Je ne sais pas encore ce que c'est.", fase = "ninfa" },
                { "Les tantes parlent de la Bête à Colle, qui vit dans les vieilles reliures et colle les mites paresseuses pour toujours.", fase = "ninfa" },
                { "J'ai demandé à grand-mère pourquoi on a peur de la lumière. Elle m'a raconté une longue histoire de soleil qui a brûlé une génération entière. Depuis, j'ai peur du soleil.", fase = "ninfa" },
                { "On m'a dit que manger le mot « fin » porte malheur. Je le saute toujours.", fase = "ninfa" },
                { "J'ai déjà noté vingt légendes. Dans dix, le monstre, c'est l'aspirateur. Ça se tient.", fase = "jovem" },
                { "On raconte que l'aspirateur est un dragon qui a perdu ses ailes et ne sait plus qu'avaler. Parfois, il me fait pitié.", fase = "jovem" },
                { "L'héroïne de nos légendes n'a pas d'épée. Elle a la faim et l'entêtement. C'est plus réaliste.", fase = "jovem" },
                { "À la pleine lune, les mites d'autrefois dansent au bord de la fenêtre. Je suis allée voir une fois. Il n'y avait que de la poussière qui dansait. C'étaient peut-être elles.", fase = "jovem" },
                { "Mon porte-bonheur, c'est une paillette trouvée sur le tapis. Je ne sais pas s'il protège. Il brille, c'est déjà ça.", fase = "jovem" },
                { "En pleine nuit, les vieilles racontent des histoires qui font peur. La meilleure, c'est celle de la Main du Plafond, qui descend quand quelqu'un mange trop fort.", quando = "noite", fase = "jovem" },
                { "Aujourd'hui, j'ai vu trois miettes en ligne droite. Selon la tradition, c'est signe d'abondance. Je les ai mangées toutes les trois pour vérifier.", quando = "feliz", fase = "jovem" },
                { "La légende dit qu'à la mue, la vieille peau emporte une peur ancienne. Elle a emporté celle du chat. Celle du balai est restée.", quando = "muda", fase = "jovem" },
                { "J'ai raconté la légende du Grand Relieur cinquante fois. Dans la version d'aujourd'hui, il avait une moustache.", fase = "adulta" },
                { "Les légendes mentent sur les détails et visent juste sur l'essentiel. C'est pour ça qu'elles durent.", fase = "adulta", curta = "Une légende ment sur le détail, pas sur l'essentiel." },
                { "Selon la tradition, le Grand Relieur reviendra à la fin des temps pour recoudre les pages volantes. J'en ai détaché quelques-unes. Je m'excuse d'avance.", fase = "adulta" },
                { "Une autre version dit qu'on vient d'une bibliothèque qui a brûlé : les cendres sont devenues des mites. Je préfère celle-là. Il y a du drame.", fase = "adulta" },
                { "Je ne crois pas aux superstitions. Mais je ne mange jamais le mot « fin », je ne dors jamais tournée vers la fenêtre et je fais toujours trois tours avant d'entrer dans un livre neuf.", fase = "adulta" },
                { "Il y a une vieille chanson sur l'aspirateur. C'est la seule chanson gaie de l'étagère : à la fin, il tombe en panne.", fase = "adulta" },
                { "À chaque nouvelle lune, je laisse une miette aux mites disparues. Elles ne la mangent pas. Mais on se souvient d'elles.", fase = "adulta" },
                { "Il y a des légendes qu'on raconte pour ne pas pleurer. Aujourd'hui, j'en ai raconté une et j'ai pleuré quand même.", quando = "triste", fase = "adulta" },
                { "Vieille, je connais toutes les légendes par cœur. J'en ai inventé quelques-unes. Personne ne se rappelle lesquelles.", fase = "ancia" },
                { "Je sens que je deviens une légende : les nymphes parlent de moi au passé, alors que je suis encore là.", fase = "ancia" },
                { "J'ai déjà choisi la dernière légende que je raconterai. Elle n'a pas de fin. C'est exprès.", fase = "ancia" },
                { "La tradition ne meurt pas. Elle change de meuble.", fase = "ancia" },
                { "J'apprends aux jeunes à raconter des histoires. C'est la seule chose que le balai ne balaie pas.", fase = "ancia", curta = "La légende, c'est ce que le balai ne balaie pas." },
                { "Quand le sommeil ne vient pas, je repasse les légendes pour ne pas les oublier. Parfois je change un détail et je fais comme si ça avait toujours été comme ça.", quando = "noite", fase = "ancia" },
                { "Quand les nymphes raconteront mon histoire, qu'elles en rajoutent. C'est le droit des morts.", fase = "ancia" },
                { "Pour les humains, c'est juste une maison. Pour les mites, c'est une terre pleine de lieux sacrés et interdits." },
                { "Je raconterais l'histoire de {personagem} aux nymphes. Je changerais la fin. C'est ce que font les grands-mères." },
                { "La vie de {personagem} a la forme des légendes : un appel, une traversée, un retour." },
                { "Chaque fois que {personagem} apparaît, je fais trois tours de reliure. Nouvelle superstition. Ça marche, pour l'instant." },
                { "J'ai parlé de {personagem} à une nymphe. Elle l'a raconté à une autre avec deux fois plus d'aventures. C'est comme ça que ça marche." },
                { "Sur l'étagère, on dit que « {livro} » abrite l'âme d'une mite ancienne. Je le mange lentement, par respect." },
                { "Dans « {livro} », il y a une page que personne ne mange. C'est la tradition. Personne ne se souvient de qui a commencé." },
                { "La légende dit que « {livro} » n'est jamais lu jusqu'au bout. Tu es en train de briser la tradition." },
                { "On raconte que {autor} a laissé dans chaque livre une bénédiction pour les mites qui mangent avec respect." },
                { "Chaque histoire de {autor} ressemble à une légende que ma grand-mère m'aurait racontée." },
                { "{evento} dans le livre. Selon la tradition, c'est signe de changement de saison." },
                { "Il y a eu {evento}, et les nymphes le racontent déjà comme si c'était arrivé sur l'étagère." },
                { "Les nymphes d'aujourd'hui n'ont jamais lu « {anterior} », mais elles en connaissent les légendes." },
                { "Le ménage d'aujourd'hui est entré dans le folklore comme {lente}." },
                { "« {palavra} » est devenu un mot de prière sur l'étagère. Personne ne sait ce que ça veut dire. Tout le monde le répète." },
                { "Toutes les légendes de l'étagère parlent {de_tema}, d'une façon ou d'une autre." },
                { "Tu figures déjà dans les légendes de l'étagère : la Grande Main qui Lit, qui tourne les pages avec soin et ne sort jamais le spray." },
                { "Tu lis chaque soir avant de dormir. Pour l'étagère, c'est déjà une tradition sacrée." },
                { "Les mites croient que si tu lis à voix haute, le livre a meilleur goût. Fais l'essai." },
                { "On raconte qu'en temps de famine, la plus vieille mite partage la reliure. Aujourd'hui, la vieille, c'est moi.", quando = "fome" },
                { "Repue. Aujourd'hui, je laisse une miette aux ancêtres.", quando = "cheia" },
                { "En pleine nuit : l'heure où les grands-mères parlent et où les nymphes ne dorment pas.", quando = "noite" },
                { "Triste comme une légende dont une seule mite se souvient.", quando = "triste" },
                { "On raconte que le balai a été un arbre, et qu'il en veut aux mites parce qu'on a mangé ses cousins." },
                { "Selon la légende, seule celle qui connaît le vrai nom du chat passe devant lui en paix. Personne ne le connaît." },
                { "Les tantes chantent aux nymphes une berceuse sur une reliure qui ne se décolle jamais." },
                { "On raconte que la mite blanche conduit les âmes jusqu'au dernier livre de l'étagère." },
                { "On raconte que dans les maisons où personne ne lit, les mites oublient leurs légendes. C'est pour ça que je prends bien soin de toi." },
                { "Chaque légende est une mite qui n'a pas voulu mourir." },
            },
            lentes = { "une légende de famille", "une vieille superstition", "un conte de revenants" },
            fechos = { "Ainsi le racontaient les anciennes.", "Celle qui raconte n'invente rien. Elle exagère.", "Il paraît que ça porte malheur de l'oublier." },
        },
        -- 16. psychologie et introspection
        psicologia = {
            frases = {
                { "J'ai remarqué que je mange toujours la marge avant le texte. Ça doit être la peur d'arriver à l'essentiel. Ou une faim de bordures. Je n'ai pas encore choisi mon diagnostic.", curta = "Je commence par la marge. Peur de l'essentiel ?" },
                { "Je dis que je n'ai peur de rien, et je dors toujours dos au mur. L'une des deux choses est un mensonge, et ce n'est pas celle du mur.", fase = { "jovem", "adulta" }, curta = "Je n'ai peur de rien. Je dors dos au mur." },
                { "Je me souviens de « {anterior} » plus que je ne devrais. Pas de l'intrigue : du goût de la colle et de l'endroit où j'étais cachée pendant la lecture." },
                { "Quand je suis triste, je mange l'index. Ce n'est pas sain, mais c'est méthodique.", quando = "triste" },
                { "Chaque fois que {personagem} apparaît, je fais trop attention. Je vais enquêter sur moi avant que ça tourne à la jalousie ou, pire, à l'identification." },
                { "Je ne sais pas encore de quoi j'ai peur. Pour l'instant, j'ai peur de tout, par précaution. Je ferai le tri plus tard.", fase = "ninfa" },
                { "J'ai mal réagi à tout aujourd'hui. C'est peut-être la mue. C'est peut-être le monde. J'ai peut-être juste besoin d'une page qui ne me demande rien.", fase = "jovem" },
                { "Le mot « {palavra} » m'agace, et je ne sais pas pourquoi. Quand un mot agace trop, en général, il a raison sur nous.", fase = "adulta" },
                { "Je revisite mes mues comme on relit de vieilles lettres. Dans chaque vieille peau est restée une version de moi qui avait peur de choses qui, aujourd'hui, m'endorment.", fase = "ancia", curta = "Dans mes vieilles peaux, des peurs qui m'endorment." },
                { "Je traite ma propre vie comme {lente}. Ma psy serait une mite plus âgée, et elle se ferait payer en papier." },
                { "Il y a eu {evento}, et j'ai réagi comme si ça me concernait. Il faut que je comprenne pourquoi, mais d'abord, que j'arrête de trembler de l'antenne." },
                { "Ce livre parle {de_tema}, et je dis que ça ne me touche pas. Je le dis la bouche pleine, c'est comme ça que je dis les mensonges importants." },
                -- nouvelles
                { "J'ai remarqué que je tremble avant de sortir de la reliure. Je ne sais pas pourquoi. Je vais m'observer.", fase = "ninfa" },
                { "Ma mère a dit que j'étais comme elle. J'ai passé une semaine à essayer d'être différente.", fase = "ninfa" },
                { "Le premier ménage m'a laissé la peur du bruit de seau. Les humains appellent ça un traumatisme. Moi, j'appelle ça un souvenir qui ne s'en va pas.", fase = "ninfa", curta = "Le bruit du seau : mon traumatisme." },
                { "J'ai trébuché sur la marge devant les autres. J'ai fait comme si c'était exprès. Je commence déjà à faire semblant.", fase = "ninfa" },
                { "Parfois je sors un peu de l'ombre juste pour voir si quelqu'un le remarque. Personne. Je rentre soulagée et triste.", fase = "ninfa" },
                { "Aujourd'hui, j'ai ressenti un truc sans nom. Je vais l'appeler « après-midi de pluie » en attendant de savoir.", fase = "ninfa" },
                { "J'ai commencé à noter mes humeurs dans la marge. J'ai découvert que ça va plus mal le mardi. J'enquête.", fase = "jovem" },
                { "Je me suis convaincue que cette mite m'était égale. Je suis restée convaincue trois jours. Le quatrième, elle ne m'était plus égale du tout.", fase = "jovem" },
                { "Les autres mites ont l'air plus courageuses. Peut-être qu'elles le sont. Peut-être qu'elles tremblent juste en dedans, comme moi.", fase = "jovem" },
                { "Je n'aime pas admettre que je suis en colère. Alors je dis que j'ai faim. Parfois, c'est la même chose.", fase = "jovem" },
                { "Grandir, c'est perdre une peau à la fois. Personne ne prévient que ça fait mal dedans aussi.", fase = "jovem" },
                { "La nuit, je repasse tout ce que j'ai fait de travers. La liste grandit dans le noir.", quando = "noite", fase = "jovem" },
                { "Aujourd'hui, je me suis sentie légère. Je ne sais pas si c'est le papier ou si j'ai enfin pardonné quelque chose.", quando = "feliz", fase = "jovem" },
                { "La mue me rend sensible. J'ai pleuré à cause d'une virgule.", quando = "muda", fase = "jovem" },
                { "Je garde en mémoire mes anciennes peaux. Celle de ma jeunesse avait plus de courage et moins de jugeote.", fase = "adulta" },
                { "Chaque fois que je vais bien, je cherche une raison de m'inquiéter. Je l'ai découvert il y a peu. Je le fais encore.", fase = "adulta" },
                { "J'imagine une mite psychanalyste qui me demande : « Et que représente la marge pour vous ? ». Je répondrais : à manger. Elle prendrait des notes.", fase = "adulta" },
                { "J'oublie ce qui me blesse et je me souviens de ce qui me fait honte. La mémoire a un drôle d'humour.", fase = "adulta" },
                { "Je me pardonne le jour et je m'accuse la nuit.", fase = "adulta" },
                { "Chaque fois que quelqu'un mange le livre que j'aime, j'ai un pincement. J'ai compris : c'est la peur de perdre.", fase = "adulta" },
                { "J'ai été peureuse, puis courageuse, puis fatiguée. Je suis toutes et aucune.", fase = "adulta" },
                { "Je suis triste. Je sais d'où ça vient. Savoir n'aide pas autant qu'on le promet.", quando = "triste", fase = "adulta" },
                { "Vieille, je relis ma vie comme un livre annoté au crayon. Certaines notes, je les effacerais. D'autres, je les soulignerais.", fase = "ancia" },
                { "J'ai appris à m'aimer comme on aime un livre usé : pour ses marques.", fase = "ancia" },
                { "Je me souviens mieux de la première page que j'ai mangée que de celle d'hier.", fase = "ancia" },
                { "La peur d'avant est devenue prudence. La prudence est devenue habitude. L'habitude est devenue moi.", fase = "ancia", curta = "La peur est devenue prudence. La prudence, moi." },
                { "Conseil de vieille : quand vous êtes en colère, demandez-vous si ce n'est pas la faim. Et inversement.", fase = "ancia" },
                { "Longue nuit, tête pleine. J'ai parlé à la jeune que j'étais. Elle ne m'a pas écoutée. Elle n'écoutait jamais.", quando = "noite", fase = "ancia" },
                { "Je n'ai plus besoin de tout comprendre en moi. Certaines pièces peuvent rester fermées à clé. Je sais où sont les clés.", fase = "ancia" },
                { "La cave, c'est là que je range ce que je ne veux pas me rappeler. L'étagère, ce que j'aime me rappeler." },
                { "Je crois que j'aime {personagem} pour ses peurs, les mêmes que les miennes. Ou pour leur absence." },
                { "Je me reconnais en {personagem} dans les pires passages. Ça en dit plus sur moi que sur le livre." },
                { "Les motivations de {personagem} me semblent évidentes. Les miennes, jamais." },
                { "{personagem} porte un souvenir comme on porte un caillou dans sa poche. Moi aussi." },
                { "J'ai choisi « {livro} » par hasard ? J'en doute. Rien de ce que je mange n'arrive par hasard." },
                { "« {livro} » a la même odeur que le livre où je suis née. J'ai passé tout un après-midi sans savoir ce que je ressentais." },
                { "Chaque fois que j'arrête de lire « {livro} », ça m'agace. Je crois que c'est la peur de finir." },
